#!/usr/bin/env bash
# Reproduce S1 lumpi-track submission 'first' (model-lumpi-track/routed-g1): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Generated by common/tools/reproduce_submission.py; scored zip model-lumpi-track/routed-g1/submissions/2026-10-02_first/submission_lumpi.zip (md5 ea2c76393d6f8868762d6bac1ac03fa8).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-lumpi-track/routed-g1/test/reproduce_first.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-lumpi-track/routed-g1/test/output/repro_first
mkdir -p $OUT
# member g1: model-lumpi-track/pointpillars-g1, checkpoint md5 16e68b8b9142688967e4b3d006ac9d54
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1/test/postprocess.yaml --out $OUT/predictions_g1.json
# member g1v3: model-lumpi-track/pointpillars-g1v3, checkpoint md5 e403acdc3ae30a84de3989da34619440
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess.yaml --out $OUT/predictions_g1v3.json
python common/tools/route_predictions.py merge model-lumpi-track/routed-g1 --pred g1=$OUT/predictions_g1.json --pred g1v3=$OUT/predictions_g1v3.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-lumpi-track/routed-g1 --tag first --compare $OUT/predictions.json
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/lumpi-track/pcdet/g1-v2/points" ]; then SYN=(--syn-split val --syn-list model-lumpi-track/routed-g1/submissions/2026-10-02_first/synthetic_ids.txt); else SYN=(--syn-zip model-lumpi-track/routed-g1/submissions/2026-10-02_first/submission_lumpi.zip --syn-list model-lumpi-track/routed-g1/submissions/2026-10-02_first/synthetic_ids.txt); fi
python common/tools/package_submission.py model-lumpi-track/routed-g1 --tag repro-first --pred $OUT/predictions.json --synthetic pcdet/g1-v2 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of first' --reproduction
Z=model-lumpi-track/routed-g1/test/output/repro-first/submission.zip
python common/tools/check_submission.py --track lumpi $Z --official
python common/tools/reproduce_submission.py model-lumpi-track/routed-g1 --tag first --compare-zip $Z     # predictions and frames against the scored zip
